declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('donor');$pdo=db();$errors=[];
if(is_post()){verify_csrf();$name=trim($_POST['name']??'');$email=trim(strtolower($_POST['email']??''));$theme=$_POST['theme']??'system';$password=$_POST['password']??'';if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Enter a name between 2 and 100 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(!in_array($theme,['light','dark','system'],true))$errors[]='Choose a valid theme preference.';if($password!==''&&strlen($password)<8)$errors[]='A new password must be at least 8 characters.';if(!$errors){$check=$pdo->prepare('SELECT id FROM users WHERE email=? AND id<>?');$check->execute([$email,$user['id']]);if($check->fetch())$errors[]='That email is already registered.';else{$pdo->beginTransaction();try{$sql='UPDATE users SET name=?,email=?'.($password!==''?',password_hash=?':'').' WHERE id=?';$params=$password!==''?[$name,$email,password_hash($password,PASSWORD_DEFAULT),$user['id']]:[$name,$email,$user['id']];$pdo->prepare($sql)->execute($params);$pref=$pdo->prepare('INSERT INTO user_preferences (user_id,theme,appointment_reminders,challenge_updates) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE theme=VALUES(theme),appointment_reminders=VALUES(appointment_reminders),challenge_updates=VALUES(challenge_updates)');$pref->execute([$user['id'],$theme,isset($_POST['appointment_reminders'])?1:0,isset($_POST['challenge_updates'])?1:0]);$pdo->commit();flash('success','Your profile and preferences were saved.');redirect('donor/profile.php');}catch(Throwable){$pdo->rollBack();$errors[]='We could not save your profile.';}}}}
$pref=$pdo->prepare('SELECT * FROM user_preferences WHERE user_id=?');$pref->execute([$user['id']]);$pref=$pref->fetch()?:['theme'=>'system','appointment_reminders'=>1,'challenge_updates'=>1];$pageTitle='Profile settings';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell" style="max-width:820px"><div class="subnav"><a href="<?=e(url('donor/dashboard.php'))?>">Dashboard</a><a href="<?=e(url('donor/passport.php'))?>">Passport</a><a href="<?=e(url('donor/notifications.php'))?>">Notifications</a><a class="is-active" href="<?=e(url('donor/profile.php'))?>">Profile settings</a></div><div class="welcome-row"><div><span class="eyebrow">Your Giftly account</span><h1>Profile settings</h1></div></div><div class="panel"><?php if($errors):?><div class="flash flash-error"><span><?=e(implode(' ',$errors))?></span></div><?php endif;?><form method="post" class="form-grid" data-loading><?=csrf_field()?><div class="field"><label for="name">Name</label><input class="input" id="name" name="name" maxlength="100" required value="<?=e($user['name'])?>"></div><div class="field"><label for="email">Email</label><input class="input" id="email" type="email" name="email" maxlength="190" required value="<?=e($user['email'])?>"></div><div class="field"><label for="theme">Theme preference</label><select class="select" id="theme" name="theme"><?php foreach(['system'=>'System default','light'=>'Light','dark'=>'Dark'] as $value=>$label):?><option value="<?=$value?>" <?=$pref['theme']===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div class="field"><label for="password">New password <small>(optional)</small></label><input class="input" id="password" type="password" name="password" minlength="8" autocomplete="new-password"></div><div class="field field-full"><label><input type="checkbox" name="appointment_reminders" <?=$pref['appointment_reminders']?'checked':''?>> Send appointment reminders</label><label style="margin-top:9px"><input type="checkbox" name="challenge_updates" <?=$pref['challenge_updates']?'checked':''?>> Send challenge milestone updates</label></div><div class="field field-full"><button class="button" type="submit">Save profile →</button></div></form></div></div></section>
